const rawInput = $json && typeof $json === 'object' ? $json : {};
const requestJson = String(rawInput.request_json || rawInput.requestJson || '').trim();
let input = rawInput;
if (requestJson) {
  try { input = JSON.parse(requestJson); } catch { throw new Error('De Excel-tool ontving ongeldige JSON-invoer.'); }
}
if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('De Excel-tool verwacht een JSON-object.');
const action = String(input.action || '').trim();
const userId = String(rawInput.userId || rawInput.user_id || '').trim();
const conversationId = String(rawInput.conversationId || rawInput.conversation_id || '').trim();
if (!['inspect_excel', 'generate_styled_excel', 'transform_excel'].includes(action)) throw new Error('Excel-toolactie is ongeldig.');
if (!userId || !conversationId) throw new Error('Geverifieerde gebruiker- of gesprekssessie ontbreekt.');
if (action === 'generate_styled_excel') {
  const headers = Array.isArray(input.headers) ? input.headers : [];
  const rows = Array.isArray(input.rows) ? input.rows : [];
  if (!headers.length) throw new Error('Voor het genereren is minstens één kolomkop vereist.');
  return [{ json: { action, userId, conversationId, filename: String(input.filename || 'provincie-limburg-tabel.xlsx'), sheetName: String(input.sheetName || 'Tabel'), headers, rows } }];
}
if (action === 'transform_excel') {
  const uploadedFile = rawInput.body?.files?.[0] || rawInput.files?.[0] || {};
  const sourceFileBase64 = String(uploadedFile.data || rawInput.sourceFileBase64 || '');
  const sourceFileName = String(uploadedFile.name || rawInput.sourceFileName || '');
  const operations = Array.isArray(input.operations) ? input.operations : [];
  if (!sourceFileBase64 || !/\.xlsx$/i.test(sourceFileName)) throw new Error('Upload een .xlsx-bestand voordat je een bewerking vraagt.');
  if (!operations.length || operations.length > 50) throw new Error('Geef 1 tot en met 50 toegestane bewerkingen op.');
  return [{ json: { action, userId, conversationId, filename: String(input.filename || `bewerkt-${sourceFileName}`), sourceFileName, sourceFileBase64, operations } }];
}
const uploadedFile = rawInput.body?.files?.[0] || rawInput.files?.[0] || {};
const fileBase64 = String(uploadedFile.data || rawInput.sourceFileBase64 || '');
const fileName = String(uploadedFile.name || rawInput.sourceFileName || 'bestand.xlsx');
if (!fileBase64) throw new Error('Voor inspectie is de binaire Excel-bijlage vereist.');
return [{ json: { action, userId, conversationId, fileBase64, fileName } }];

const input = $json;
const baseUrl = String($env.EXCEL_WORKER_URL || 'http://excel-worker:8080').replace(/\/$/, '');
const token = String($env.EXCEL_INTERNAL_API_TOKEN || '').trim();
if (!token) throw new Error('Excel service token ontbreekt.');
const headers = { Authorization: 'Bearer ' + token };
const http = require('http');
const https = require('https');
const { URL } = require('url');
function request(url, options, body) {
  return new Promise((resolve, reject) => {
    const target = new URL(url);
    const client = target.protocol === 'https:' ? https : http;
    const req = client.request({ protocol: target.protocol, hostname: target.hostname, port: target.port, path: target.pathname + target.search, method: options.method || 'POST', headers: options.headers || {} }, (res) => {
      let text = '';
      res.setEncoding('utf8');
      res.on('data', (chunk) => { text += chunk; });
      res.on('end', () => resolve({ status: res.statusCode || 0, text }));
    });
    req.on('error', reject);
    req.setTimeout(120000, () => req.destroy(new Error('Excel-service timeout.')));
    if (body) req.write(body);
    req.end();
  });
}
let response;
if (input.action === 'generate_styled_excel') {
  const body = JSON.stringify({ userId: input.userId, conversationId: input.conversationId, filename: input.filename, sheetName: input.sheetName, headers: input.headers, rows: input.rows });
  response = await request(baseUrl + '/v1/generate', { headers: { ...headers, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, body);
} else if (input.action === 'transform_excel') {
  const body = JSON.stringify({ userId: input.userId, conversationId: input.conversationId, filename: input.filename, sourceFileName: input.sourceFileName, sourceFileBase64: input.sourceFileBase64, operations: input.operations });
  response = await request(baseUrl + '/v1/transform', { headers: { ...headers, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, body);
} else {
  throw new Error('Excel-inspectie via bestandsbijlage wordt in deze eerste toolversie nog niet ondersteund.');
}
let payload = {};
try { payload = JSON.parse(response.text); } catch {}
if (response.status < 200 || response.status >= 300 || !payload.ok) throw new Error(String(payload.detail || 'Excel-verwerking is mislukt.'));
return [{ json: { action: input.action, result: payload } }];

const { action, result } = $json;
if (action === 'generate_styled_excel' || action === 'transform_excel') {
  const date = new Intl.DateTimeFormat('nl-NL', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Europe/Amsterdam' }).format(new Date(result.createdAt));
  const fileName = String(result.fileName || 'excel-bestand.xlsx').replace(/[\[\]
]/g, '');
  const changeText = action === 'transform_excel' ? `
> **Uitgevoerd:** ${(result.changes || []).map((change) => change.type).join(', ') || 'bewerkingen'}` : '';
  const response = `## Excel-bestand gereed

> **Bestand:** \`${fileName}\`  
> **Inhoud:** ${result.rowCount} rijen  
> **Aangemaakt:** ${date}${changeText}

[📥 Download ${fileName}](${result.downloadPath})`;
  return [{ json: { response, artifact: { type: 'file', mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName, downloadPath: result.downloadPath, rowCount: result.rowCount, createdAt: result.createdAt } } }];
}
const sheets = Array.isArray(result.sheets) ? result.sheets : [];
const overview = sheets.map((sheet) => `### ${sheet.name}
Kolommen: ${(sheet.columns || []).join(', ') || 'geen'}
Voorbeeldrijen: ${JSON.stringify(sheet.sampleRows || [])}`).join('

');
return [{ json: { response: `## Excel-inspectie: ${result.fileName}

${overview || 'Geen werkbladen gevonden.'}`, inspection: { fileName: result.fileName, sheets } } }];
